contract InvMutTest {
    C c;
    address private target;
    bool private callbackSeen;

    constructor(C _c) {
        c = _c;
        target = address(new Reverter());
    }

    function run(bool useReverter) public payable {
        address callee;
        if (useReverter) {
            callee = target;
        } else {
            InvMutTest self = this;
            callee = address(self);
        }

        bytes memory data = abi.encodeWithSignature("probe()");
        callbackSeen = false;

        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == useReverter);
    }

    receive() external payable {}

    fallback() external payable {
        callbackSeen = true;
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

